import{_ as i,o as s,c as e,ak as t}from"./chunks/framework.DJ-92fJv.js";const k=JSON.parse('{"title":"🌐 解锁网络限制","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/unlock-network.md","filePath":"features/unlock-network.md"}'),l={name:"features/unlock-network.md"};function n(h,a,r,d,c,o){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="🌐-解锁网络限制" tabindex="-1">🌐 解锁网络限制 <a class="header-anchor" href="#🌐-解锁网络限制" aria-label="Permalink to “🌐 解锁网络限制”">​</a></h1><p><strong>主菜单选项：<code>2</code></strong></p><p>当仅需要解除网络限制（恢复上网功能）时，可以使用此功能。它不会影响其他方面。</p><h2 id="执行内容" tabindex="-1">执行内容 <a class="header-anchor" href="#执行内容" aria-label="Permalink to “执行内容”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─ 停止 MMPC 服务 ───── 学生端根服务，关闭后断开与学生端管理系统的连接</span></span>
<span class="line"><span>├─ 停止 OeNetlimit 服务 ─ 网络限制服务，解除对网络访问的过滤和封锁</span></span>
<span class="line"><span>├─ 终止 Student.exe ──── 学生端主程序，停止网络管控逻辑</span></span>
<span class="line"><span>└─ 终止 DeviceControl_x64.exe ─ 设备控制进程，解除设备层面的网络限制</span></span></code></pre></div><h2 id="手动执行命令" tabindex="-1">手动执行命令 <a class="header-anchor" href="#手动执行命令" aria-label="Permalink to “手动执行命令”">​</a></h2><p>如果你身边没有工具，可以直接在 CMD（管理员身份）中依次执行以下命令：</p><h3 id="命令-1-停止学生端核心服务" tabindex="-1">命令 1：停止学生端核心服务 <a class="header-anchor" href="#命令-1-停止学生端核心服务" aria-label="Permalink to “命令 1：停止学生端核心服务”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stop MMPC</span></span></code></pre></div><p>停止学生端根服务（MMPC），这是控制所有学生端功能的中心服务。</p><h3 id="命令-2-停止网络限制服务" tabindex="-1">命令 2：停止网络限制服务 <a class="header-anchor" href="#命令-2-停止网络限制服务" aria-label="Permalink to “命令 2：停止网络限制服务”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stop OeNetlimit</span></span></code></pre></div><p>停止专门的网络过滤和限制服务，解除对上网的限制。</p><h3 id="命令-3-终止学生端主进程" tabindex="-1">命令 3：终止学生端主进程 <a class="header-anchor" href="#命令-3-终止学生端主进程" aria-label="Permalink to “命令 3：终止学生端主进程”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im Student.exe</span></span></code></pre></div><p>强制终止学生端主程序 <code>Student.exe</code>，防止其继续执行网络管控逻辑。</p><h3 id="命令-4-终止设备控制进程" tabindex="-1">命令 4：终止设备控制进程 <a class="header-anchor" href="#命令-4-终止设备控制进程" aria-label="Permalink to “命令 4：终止设备控制进程”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im DeviceControl_x64.exe</span></span></code></pre></div><p>强制终止设备控制进程，解除设备层面的网络限制。</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><ul><li>✅ 老师开启了 <strong>上网限制</strong>，只能访问指定网站</li><li>✅ 机房设置了 <strong>网页过滤</strong>，无法访问学习资源</li><li>✅ 只需要上网，不需要解锁其他限制</li></ul><h2 id="效果说明" tabindex="-1">效果说明 <a class="header-anchor" href="#效果说明" aria-label="Permalink to “效果说明”">​</a></h2><p>解锁后你应该可以：</p><ul><li>正常访问所有网站</li><li>使用浏览器搜索资料</li><li>下载文件（如受其他限制，可能仍需解锁对应项）</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="q-解锁后任务栏的网络图标仍然显示-无internet" tabindex="-1">Q：解锁后任务栏的网络图标仍然显示&quot;无Internet&quot;？ <a class="header-anchor" href="#q-解锁后任务栏的网络图标仍然显示-无internet" aria-label="Permalink to “Q：解锁后任务栏的网络图标仍然显示&quot;无Internet&quot;？”">​</a></h3><p>这是正常现象，网络状态指示刷新有延迟。<strong>直接打开浏览器访问任意网站</strong>，网络实际上已经恢复正常。</p><h3 id="q-重启电脑后网络又被限制了" tabindex="-1">Q：重启电脑后网络又被限制了？ <a class="header-anchor" href="#q-重启电脑后网络又被限制了" aria-label="Permalink to “Q：重启电脑后网络又被限制了？”">​</a></h3><p><code>sc stop</code> 只是临时停止服务，重启后服务会自动恢复。如果需要永久解除，可以执行：</p><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delete MMPC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delete OeNetlimit</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">警告</p><p>删除服务是不可逆操作，只有重新安装噢易软件才能恢复。</p></div><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>部分网络限制可能在重启 <code>MMPC</code> 服务后恢复。如需持久解锁，建议配合 <strong>服务管理</strong> 中的删除服务操作。</p></div>`,33)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
